const OWN = 'n8n.opc@gmail.com';
const TZ = 'Europe/Istanbul';
const PER_SENDER_DAY = 3;
const ALL_DAY = 100;
const AI_DAY = 100;
const MAX_PDFS = 1;
const AUTOMATED = /^(mailer-daemon|postmaster|bounces?|no-?reply|do-?not-?reply|notifications?)([+.-].*)?@/i;
const mask = (a) => {
  const at = a.lastIndexOf('@');
  const local = a.slice(0, at);
  const masked = local.length <= 1 ? local + '***' : local[0] + '***' + local[local.length - 1];
  return masked + '@' + a.slice(at + 1);
};
const state = $getWorkflowStaticData('global');
const today = DateTime.now().setZone(TZ).toISODate();
if (state.day !== today) { state.day = today; state.bySender = {}; state.total = 0; state.ai = 0; }
state.ai = state.ai || 0;
const out = [];
$input.all().forEach((item, index) => {
  const m = item.json;
  const sender = String((m.from && m.from.value && m.from.value[0] && m.from.value[0].address) || '').toLowerCase();
  const when = (m.date ? DateTime.fromISO(String(m.date)) : DateTime.now()).setZone(TZ);
  const automated = !sender || sender === OWN || AUTOMATED.test(sender);
  const used = state.bySender[sender] || 0;
  const replyAllowed = !automated && used < PER_SENDER_DAY && state.total < ALL_DAY;
  if (replyAllowed) { state.bySender[sender] = used + 1; state.total += 1; }
  const base = {
    messageId: m.id,
    received: when.toFormat('yyyy-MM-dd HH:mm'),
    fromMasked: sender ? mask(sender) : '(unknown)',
    subject: String(m.subject || '').slice(0, 120),
    replyAllowed,
    automated,
  };
  const binary = item.binary || {};
  const pdfKeys = Object.keys(binary).filter((k) => {
    const b = binary[k] || {};
    return String(b.mimeType || '').toLowerCase() === 'application/pdf' || /\.pdf$/i.test(String(b.fileName || ''));
  });
  if (!pdfKeys.length || automated) {
    out.push({ json: { ...base, fileName: '', pdfCount: 0, aiAllowed: false, status: automated ? 'automated sender' : 'no PDF attached' }, pairedItem: { item: index } });
    return;
  }
  pdfKeys.slice(0, MAX_PDFS).forEach((k) => {
    const aiAllowed = state.ai < AI_DAY;
    if (aiAllowed) state.ai += 1;
    out.push({
      json: { ...base, fileName: String(binary[k].fileName || 'invoice.pdf').slice(0, 80), pdfCount: pdfKeys.length, aiAllowed, status: '' },
      binary: { data: binary[k] },
      pairedItem: { item: index },
    });
  });
});
return out;

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "is_invoice": { "type": "boolean", "description": "true if the document is an invoice or a bill asking for payment" },
    "vendor_name": { "type": "string", "description": "The issuing company (seller), as printed; empty string if not found" },
    "invoice_number": { "type": "string", "description": "The invoice number as printed; empty string if not found" },
    "invoice_date": { "type": "string", "description": "Issue date as YYYY-MM-DD; empty string if not found" },
    "due_date": { "type": "string", "description": "Payment due date as YYYY-MM-DD; if only payment terms are given (e.g. net 30), compute it from the invoice date; empty string if not found" },
    "currency": { "type": "string", "description": "ISO 4217 code such as EUR, USD, TRY, GBP; empty string if unclear" },
    "subtotal": { "type": ["number", "null"], "description": "Net amount before tax, plain number without separators; null if not printed" },
    "tax": { "type": ["number", "null"], "description": "Total tax / VAT amount; null if not printed" },
    "total": { "type": ["number", "null"], "description": "Gross amount due; null if not printed" },
    "line_items": {
      "type": "array",
      "description": "Every invoice line, in order",
      "items": {
        "type": "object",
        "properties": {
          "description": { "type": "string" },
          "quantity": { "type": ["number", "null"] },
          "unit_price": { "type": ["number", "null"] },
          "amount": { "type": ["number", "null"], "description": "Line net amount" }
        },
        "required": ["description", "quantity", "unit_price", "amount"]
      }
    }
  },
  "required": ["is_invoice", "vendor_name", "invoice_number", "invoice_date", "due_date", "currency", "subtotal", "tax", "total", "line_items"]
}

