const p = $('Pick the PDF invoice').item.json;
const j = $json || {};
const o = j.output || null;
const ADDR = /[^\s<>,;"']+@[^\s<>,;"']+\.[^\s<>,;"']+/g;
const scrub = (s, n) => {
  const t = String(s || '').replace(ADDR, '[email]').replace(/https?:\/\/\S+|www\.\S+/gi, '[link]').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '\u2026' : t;
};
const num = (v) => {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (typeof v === 'string' && v.trim() !== '' && isFinite(Number(v.replace(/[\s,]/g, '')))) return Number(v.replace(/[\s,]/g, ''));
  return null;
};
const money = (n) => (n === null ? '' : n.toFixed(2));
const isoDate = (s) => (/^\d{4}-\d{2}-\d{2}$/.test(String(s || '')) ? String(s) : '');
let status = p.status || '';
if (!status && !o) {
  if (j.error) status = 'could not read or analyze the PDF';
  else if (String(j.text || '').trim().length < 40) status = 'no text layer (scanned PDF?)';
  else if (!p.aiAllowed) status = 'not analyzed (daily AI limit)';
  else status = 'could not analyze';
}
const row = {
  log: !p.status,
  messageId: p.messageId,
  replyAllowed: p.replyAllowed,
  pdfCount: p.pdfCount,
  Received: p.received,
  From: p.fromMasked,
  Subject: scrub(p.subject, 120),
  File: p.fileName || '',
  Vendor: '', 'Invoice no': '', 'Invoice date': '', 'Due date': '', Currency: '',
  Subtotal: '', Tax: '', Total: '', Items: '', Check: status,
  lines: [],
};
if (o && !status) {
  const lines = (Array.isArray(o.line_items) ? o.line_items : []).slice(0, 50).map((l) => {
    const q = num(l.quantity); const u = num(l.unit_price); let a = num(l.amount);
    if (a === null && q !== null && u !== null) a = Math.round(q * u * 100) / 100;
    return { d: scrub(l.description, 80), q, u, a };
  });
  const subtotal = num(o.subtotal); const tax = num(o.tax); const total = num(o.total);
  const lineSum = Math.round(lines.reduce((s, l) => s + (l.a || 0), 0) * 100) / 100;
  const invDate = isoDate(o.invoice_date); const due = isoDate(o.due_date);
  const issues = [];
  if (o.is_invoice === false) issues.push('not an invoice');
  if (total === null && o.is_invoice !== false) issues.push('no total found');
  if (lines.length && subtotal !== null && Math.abs(lineSum - subtotal) > 0.02) issues.push('lines ' + money(lineSum) + ' \u2260 subtotal ' + money(subtotal));
  if (lines.length && subtotal === null && tax === null && total !== null && Math.abs(lineSum - total) > 0.02) issues.push('lines ' + money(lineSum) + ' \u2260 total ' + money(total));
  if (subtotal !== null && tax !== null && total !== null && Math.abs(subtotal + tax - total) > 0.02) issues.push('subtotal + tax \u2260 total');
  if (invDate && due && due < invDate) issues.push('due date before invoice date');
  Object.assign(row, {
    Vendor: scrub(o.vendor_name, 60),
    'Invoice no': scrub(o.invoice_number, 30),
    'Invoice date': invDate,
    'Due date': due,
    Currency: /^[A-Z]{3}$/.test(String(o.currency || '').toUpperCase()) ? String(o.currency).toUpperCase() : '',
    Subtotal: money(subtotal), Tax: money(tax), Total: money(total),
    Items: String(lines.length),
    Check: issues.length ? 'check: ' + issues.join('; ') : 'OK',
    lines,
  });
}
return { json: row };

const KEEP = 10;
const COLS = ['Received', 'From', 'Subject', 'File', 'Vendor', 'Invoice no', 'Invoice date', 'Due date', 'Currency', 'Subtotal', 'Tax', 'Total', 'Items', 'Check'];
const pick = (r) => Object.fromEntries(COLS.map((c) => [c, r[c] === undefined || r[c] === null ? '' : String(r[c])]));
const fresh = $('Check totals and build row').all().map((i) => i.json).filter((r) => r.log).map(pick);
const old = $('Read invoice log').all().map((i) => i.json).filter((r) => r && r.Received).map(pick);
return [...fresh.reverse(), ...old]
  .map((r, i) => ({ r, i }))
  .sort((a, b) => String(b.r.Received).localeCompare(String(a.r.Received)) || a.i - b.i)
  .slice(0, KEEP)
  .map(({ r }) => ({ json: r }));

const SHEET = 'https://docs.google.com/spreadsheets/d/1JLRIXDWSOEjCvY0FFsUgZDuReg5NtRw9gNc7QUnVTjY';
const fmt = (n) => (n === null || n === undefined ? '?' : Number(n).toFixed(2));
const groups = {};
const order = [];
$input.all().forEach((i) => {
  const r = i.json;
  if (!groups[r.messageId]) { groups[r.messageId] = []; order.push(r.messageId); }
  groups[r.messageId].push(r);
});
return order.map((id) => {
  const rows = groups[id];
  const parts = rows.map((r) => {
    if (!r.log) return 'No PDF invoice was found in your email. Attach one PDF (text-based, not a scan, under 5 MB) and send it again.';
    const head = '\u2022 ' + (r.File || 'PDF') + (r.pdfCount > 1 ? ' (only the first PDF is read)' : '');
    if (!r.Vendor && !r.Total) return head + '\n  Result: ' + r.Check;
    const lines = (r.lines || []).slice(0, 15).map((l) => '    - ' + l.d + ' \u2014 ' + (l.q === null ? '?' : l.q) + ' \u00d7 ' + fmt(l.u) + ' = ' + fmt(l.a)).join('\n');
    return [
      head,
      '  Vendor: ' + (r.Vendor || '?'),
      '  Invoice no.: ' + (r['Invoice no'] || '?'),
      '  Invoice date: ' + (r['Invoice date'] || '?') + '   Due: ' + (r['Due date'] || '?'),
      '  Subtotal / Tax / Total: ' + (r.Currency || '') + ' ' + (r.Subtotal || '?') + ' / ' + (r.Tax || '?') + ' / ' + (r.Total || '?'),
      '  Line items (' + r.Items + '):' + (lines ? '\n' + lines : ' none found'),
      '  Check: ' + r.Check,
    ].join('\n');
  });
  const anyLogged = rows.some((r) => r.log);
  const body = 'Hi,\n\nThanks for trying the vosk.dev invoice parser. This is what the workflow read from your email:\n\n'
    + parts.join('\n\n')
    + (anyLogged ? '\n\nThe public sheet keeps the 10 newest parsed invoices:\n' + SHEET : '')
    + '\n\nThis reply was sent automatically by an n8n workflow; an LLM read the text of the PDF. Please send only the sample invoices from vosk.dev or other test invoices: the sheet is public.\n\nvosk.dev';
  return { json: { messageId: id, replyAllowed: rows[0].replyAllowed, body } };
});
